var order='sync';var innerThenable={then:function(resolve,reject){order=order+'-inner';resolve('Nested thenable final');}};var outerThenable={then:function(resolve,reject){order=order+'-outer';resolve(innerThenable);}};Promise.resolve(outerThenable).then(function(value){order=order+'-fulfilled';document.getElementById('nested').textContent=value;document.getElementById('nested').setAttribute('class','nested');document.getElementById('order').textContent=order;});var selfThenable={then:function(resolve,reject){resolve(selfThenable);}};Promise.resolve(selfThenable).catch(function(reason){return 'Self recovered';}).then(function(value){document.getElementById('self').textContent='Self thenable rejected '+value;});var brokenThenable={then:function(resolve,reject){fetch(42);}};Promise.resolve(brokenThenable).catch(function(reason){return 'Error recovered';}).then(function(value){document.getElementById('error').textContent='Thenable job error rejected '+value;document.getElementById('error').setAttribute('class','error');});order=order+'-tail';document.getElementById('order').textContent=order;
